import{z as A,x as d,o as t,c as B,q as n,j as s,D as r,d as E,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"随机化算法的实践","description":"","frontmatter":{"title":"随机化算法的实践","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ae-randomized-practice.md","filePath":"cs/ae-randomized-practice.md","lastUpdated":1791413859000}'),p={name:"cs/ae-randomized-practice.md"};function m(D,a,c,C,h,F){const o=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=n('<h1 id="随机化算法的实践" tabindex="-1">随机化算法的实践 <a class="header-anchor" href="#随机化算法的实践" aria-label="Permalink to &quot;随机化算法的实践&quot;">​</a></h1><div class="epigraph"><p>随机化把最坏情况从输入手里买回来：对手从此挑不了你的数组，只能挑你的硬币。</p><footer>—— 据 Motwani and Raghavan, Randomized Algorithms, 1995 整理</footer></div><p><a href="/cs/ae-bit-tricks">上一课</a>把字内并行收拢后，本课转向第三类工程杠杆：掷硬币。主干课的<a href="/cs/quicksort-expected">快排与期望</a>推过随机主元的 \\(O(n\\log n)\\) 期望界，<a href="/cs/pollard-rho">Pollard rho</a> 用随机游走找因子；本课把它们当同一件工程工具收拢成三问：掷什么、怎么掷、怎么守。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定启发式最怕对手。固定取首元素为主元的快排，遇上构造好的输入退化为 \\(\\Theta(n^2)\\)；固定哈希函数加上公开的键，攻击者能批量造出同桶键——2011 年前后多个 Web 框架因此被哈希碰撞攻击拖垮，纷纷引入随机化种子。缺口是把最坏情况的控制权从输入手里拿回来。不这么做会错在三处：<code>rand() % n</code> 的模偏置让靠前的元素被抽中得多一点，采样分析全歪；用时间戳做种子，同一秒启动的进程拿到同一序列，等于没掷；把 Monte Carlo 的近似答案当精确值上报，误差没人兜底。</p><p><span class="marginnote">术语翻译：Las Vegas 算法用「耗时不确定」换「结果永远正确」——它宁可多掷几轮也不给错答案（如随机化快排）；Monte Carlo 反过来，用「结果可能错、但错率有界」换「耗时固定」。报告结果时动词要配对：前者说「期望多少步」，后者说「错误率不超过多少」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>掷什么：排序类用随机主元与 Fisher–Yates 洗牌（从后往前，每个剩余位置等概率交换）打底；哈希表用种子化哈希，把碰撞从「对手可构造」变成「期望事件」；平衡结构用 <a href="/cs/treap">Treap</a>——按随机优先级旋转，无需手调平衡因子——与<a href="/cs/skip-list">跳表</a>；内存换精度用<a href="/cs/bloom-filter">布隆过滤器</a>。</p><p>怎么掷：均匀区间要用拒绝采样，或只在整除关系成立时取模，否则偏置；种子取自高熵源，并且<strong>记下来</strong>——种子是实验参数，不是废弃物。</p><p>怎么守：Las Vegas（永不错、只随机耗时，如随机化快排）与 Monte Carlo（可能错、错率有界，如布隆过滤器）分开标记，接口与文档注明各自动词。验证走配对：同一组种子跑新旧两版实现，方差立刻小一圈，配对的意义在基准一课展开。</p>',10)),(t(),s(i,null,{default:r(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIX%5B%22%E5%9B%BA%E5%AE%9A%E5%90%AF%E5%8F%91%E5%BC%8F%EF%BC%9A%E5%AF%B9%E6%89%8B%E5%8F%AF%E6%9E%84%E9%80%A0%E6%9C%80%E5%9D%8F%E8%BE%93%E5%85%A5%22%5D%20--%3E%20COIN%5B%22%E5%BC%95%E5%85%A5%E7%A1%AC%E5%B8%81%EF%BC%9A%E9%9A%8F%E6%9C%BA%E4%B8%BB%E5%85%83%20%2F%20%E7%A7%8D%E5%AD%90%20%2F%20%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20COIN%20--%3E%20LV%5B%22Las%20Vegas%EF%BC%9A%E6%9C%9F%E6%9C%9B%E8%80%97%E6%97%B6%22%5D%0A%20%20COIN%20--%3E%20MC%5B%22Monte%20Carlo%EF%BC%9A%E6%9C%89%E7%95%8C%E9%94%99%E8%AF%AF%E7%8E%87%22%5D%0A%20%20LV%20--%3E%20SEED%5B%22%E8%AE%B0%E5%BD%95%E7%A7%8D%E5%AD%90%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20MC%20--%3E%20SEED%0A%20%20SEED%20--%3E%20VER%5B%22%E9%85%8D%E5%AF%B9%E7%A7%8D%E5%AD%90%E5%A4%8D%E7%8E%B0%E4%B8%8E%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("随机化为什么赢在对手模型：期望界是对硬币分布取的，不假设输入分布——对手必须先于你的硬币做决定，于是「最坏输入」不存在，只剩「最坏运气」，而运气可控。这正是"),e("a",{href:"/cs/adversary-argument"},"对手论证"),E("那套下界技巧的反面用法：既然比较下界盯得住确定性算法，随机化就换一个被平均的对象。两档保证各有账目：期望界由 Markov 一族不等式升级为高概率界；近似结构的误差由公式给出，不是拍脑袋。随机化通常还附带实现红利：随机主元的快排比手调三数取中简单，Treap 比红黑树少一半分支，省下的复杂度本身就是常数。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"布隆过滤器的账：每键 \\(m/n=8\\) 比特、\\(k=6\\) 个哈希（接近最优）时误报率约 2.2%；压到 0.1% 要 \\(m/n\\approx 15\\)。随机化的代价要显式记账，它才不会被当成免费的魔法。")],-1)),a[6]||(a[6]=e("p",null,[E("方法一节的图回答「随机化分哪几类、怎么守」，下面这张回答另一个问题："),e("code",null,"rand() % n"),E(" 的偏置从哪来，拒绝采样怎么把它修平。")],-1)),(t(),s(i,null,{default:r(()=>[l(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22rand()%20%E5%9D%87%E5%8C%80%E8%BF%94%E5%9B%9E%20%5B0%2C%20R)%22%5D%20--%3E%20Q%7B%22n%20%E6%95%B4%E9%99%A4%20R%20%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20OK%5B%22%E5%8F%96%E6%A8%A1%E5%8D%B3%E5%9D%87%E5%8C%80%3A%20%E6%AF%8F%E4%B8%AA%E4%BD%99%E6%95%B0%E7%AD%89%E6%A6%82%E7%8E%87%22%5D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20BIAS%5B%22%E5%8F%96%E6%A8%A1%E6%9C%89%E5%81%8F%3A%20%E5%8C%BA%E9%97%B4%E9%9D%A0%E5%89%8D%E7%9A%84%E4%BD%99%E6%95%B0%E8%A2%AB%E5%A4%9A%E6%8A%BD%22%5D%0A%20%20BIAS%20--%3E%20FIX%5B%22%E6%8B%92%E7%BB%9D%E9%87%87%E6%A0%B7%3A%20%E4%BB%A4%20limit%20%3D%20R%20-%20(R%20mod%20n)%22%5D%0A%20%20FIX%20--%3E%20LOOP%7B%22%E6%8A%BD%E5%87%BA%E7%9A%84%E5%80%BC%20%E2%89%A5%20limit%3F%22%7D%0A%20%20LOOP%20--%20%22%E6%98%AF%2C%20%E5%BC%83%E6%8E%89%E9%87%8D%E6%8A%BD%22%20--%3E%20FIX%0A%20%20LOOP%20--%20%22%E5%90%A6%22%20--%3E%20OK%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：设 <code>rand()</code> 返回 \\([0,32767]\\)、\\(n=20000\\)——余数 \\(0\\) 到 \\(12767\\) 能由两个源值取模得到，概率约 \\(2/32768\\)；余数 \\(12768\\) 到 \\(19999\\) 只有一个源值，概率约 \\(1/32768\\)。前一小半元素被抽中的概率几乎是后一半的两倍，采样分析就此全歪。</span></p><p><span class="marginnote">直觉类比：随机主元像切蛋糕前让一个旁观者闭眼指一刀——每位客人猜不到自己会分到哪块，谁也没法提前站位（构造最坏输入）；固定主元则是每次都从同一位置下刀，排好队的人（对手输入）早把最大的那块留给了位置。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>密码学场景的随机源是另一门课：普通 PRNG 的输出可预测，种子一旦可推断，本课的一切保证作废。可复现性要求种子随实验归档——不能复现的随机结果既无法 debug，也进不了回归测试。随机化不豁免正确性测试：期望界不担保任何单次运行，空输入、全同元素这类边界仍要用确定性用例钉住。本课只到「期望与高概率」为止；近似算法的误差-时间谱系与计数估计，是近似课程的主题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机化把最坏输入换成最坏运气：期望界或高概率界，对手先于硬币行动。</li><li>常用五件：随机主元与 Fisher–Yates、种子化哈希、Treap、跳表、布隆过滤器。</li><li>随机源是正确性的一部分：拒绝采样防模偏置，高熵种子，用后归档。</li><li>Las Vegas 与 Monte Carlo 分开标记，误差与耗时谁在掷硬币要写清楚。</li><li>出处：Motwani and Raghavan, <em>Randomized Algorithms</em>, 1995；Mitzenmacher and Upfal, <em>Probability and Computing</em>, 2005；Bloom, 1970。</li></ul>',6))])}const g=A(p,[["render",m]]);export{u as __pageData,g as default};
